fun findUser(id: Long): User? = repo.firstOrNull { it.id == id }

fun displayName(id: Long): String {
    val user = findUser(id) ?: return "desconhecido"
    return user.name.uppercase()
}

// Smart cast: compilador sabe que nao e nulo
fun log(u: User?) {
    if (u == null) return
    println(u.name)   // sem !! nem ?.
}

