inline fun <T> medir(tag: String, block: () -> T): T {
    val start = System.nanoTime()
    val r = block()
    val ms = (System.nanoTime() - start) / 1_000_000
    println("$tag: ${ms}ms")
    return r
}

val users = medir("fetch") { repo.all() }
